typedef unsigned int size_t;
typedef unsigned char *PointerMath;
typedef size_t MemSize;
typedef int MemSizeDiff;
typedef unsigned int MemFlags;

#define NULL 0
#define CHECKFORERRORS ((void)0)
#define heapassert(exp) ((void)0)

enum MemoryAllocationFlags
{
	mafNone      = 0x00,
	mafHigh      = 0x01,
};

class MemBlockInfo
{
	public:
	MemBlockInfo *prev;
	MemBlockInfo *next;
	MemBlockInfo *prevoftype;
	MemBlockInfo *nextoftype;
	MemSize size;
	bool CanHold( MemSize size, MemSize align, MemFlags flags, MemSize headersize );
};

inline MemSize RoundUp( MemSize size, MemSize align )
{
	return (size + ((align)-1)) & ~((align)-1);
}

inline MemSize RoundDown( MemSize size, MemSize align )
{
	return (size) & ~((align)-1);
}

inline PointerMath PtrAlign( PointerMath ptr, MemSize align )
{
	MemSize iptr=(MemSize) ptr;
	iptr = RoundUp(iptr,align);
	return (PointerMath) iptr;
}

inline PointerMath PtrAlignLow( PointerMath ptr, MemSize align )
{
	MemSize iptr=(MemSize) ptr;
	iptr = RoundDown(iptr,align);
	return (PointerMath) iptr;
}

class Heap
{
	MemBlockInfo *fullhead;
	MemBlockInfo *fulltail;
	MemBlockInfo *usedhead;
	MemBlockInfo *usedtail;
	MemBlockInfo *freehead;
	MemBlockInfo *freetail;
	MemSize heapsize;
	void *heapstart;
	MemSize allocatedblocks;
	MemSize minalloc;

	public:
	static void Error( const char* Format, ... );
	MemSize HeaderSize( void ) const;
	MemSize FooterSize( void ) const;
	MemBlockInfo *ShiftBlock( MemBlockInfo *block, MemSizeDiff diff );
	MemBlockInfo *SplitBlock( MemBlockInfo *block, MemSize blocksize );
	MemBlockInfo *AllocSplit( MemBlockInfo *block, MemSize size, MemSize align, MemFlags flags );
};

